# -*- coding: utf-8 -*-
"""Nội dung mới của Chương 2 (sau tái cấu trúc) - bản rút gọn lần 2.

Mỗi phần tử của BLOCKS là một tuple:
  ('h2', idx_goc, 'tiêu đề mới')   -> giữ đoạn Heading 2 gốc (bookmark, paraId), đổi chữ
  ('h3', idx_goc, 'tiêu đề mới')   -> giữ đoạn Heading 3 gốc, đổi chữ
  ('p',  'văn bản')                -> đoạn mới, style "Nội dung" (176); **...** là chữ đậm
  ('p177', 'văn bản')              -> đoạn mới, style "Nội dung sau bảng" (177)
  ('orig', idx_goc)                -> giữ nguyên phần tử gốc (đoạn văn, chú thích bảng, bảng)
idx_goc là chỉ số phần tử con của <w:body> trong tệp gốc.
"""

CH2_FIRST = 300   # phần tử đầu tiên sau tiêu đề chương 2
CH2_LAST = 377    # bảng 2.4 (phần tử cuối của chương 2)

BLOCKS = [
    ('orig', 300),   # đoạn giới thiệu chương: giữ nguyên, vẫn đúng với 8 mục 2.1-2.8

    # ------------------------------------------------------------------ 2.1
    ('h2', 301, 'Hệ thống thông tin quản lý nông trại và đặc thù nông hộ quy mô nhỏ'),
    ('p', 'Hệ thống thông tin quản lý nông trại (FMIS) là hệ thống thu thập, xử lý, lưu trữ và phân phối dữ liệu cần thiết cho việc điều hành các hoạt động của nông trại [3]. Các chức năng thường gặp gồm lập kế hoạch sản xuất, ghi nhật ký thực hiện công việc, quản lý vật tư và quản lý tài chính, nhưng phạm vi chức năng của từng hệ thống rất khác nhau; tổng quan tài liệu về FMIS ghi nhận sự khác biệt này và xác định các đặc tính cần có như khả năng ghi chép thuận tiện, báo cáo và tích hợp dữ liệu [4]. Về mặt kiến trúc, một FMIS hiện đại thường được xem là một thành phần trong hệ sinh thái phần mềm nông nghiệp, trao đổi dữ liệu với nhiều bên liên quan [9].'),
    ('p', 'Đối với nông hộ quy mô nhỏ, các rào cản phổ biến khi tiếp cận FMIS là chi phí, độ phức tạp và khả năng sử dụng [4]. Mô hình khái niệm FMIS cho nông hộ nhỏ được đề xuất trong nghiên cứu về nông hộ trồng ớt tại Indonesia nhấn mạnh sự cần thiết của một hệ thống đơn giản, tập trung vào những chức năng cốt lõi [5]. Ở khu vực nông thôn, hạ tầng kết nối còn hạn chế cũng là một ràng buộc thiết kế quan trọng [1]. Những đặc thù này dẫn tới ba định hướng của AgriLog V2: giao diện đơn giản trên thiết bị di động, vận hành được khi mất kết nối, và dữ liệu có cấu trúc để tổng hợp chi phí theo lô. Định hướng thứ hai là lý do của kiến trúc ưu tiên ngoại tuyến ở mục 2.2; định hướng thứ ba đặt ra yêu cầu về mô hình dữ liệu và giao dịch ở mục 2.4.'),

    # ------------------------------------------------------------------ 2.2
    ('h2', 306, 'Kiến trúc ưu tiên ngoại tuyến và đồng bộ dữ liệu'),
    ('p', 'Điện toán di động đối mặt với những thách thức cố hữu như chất lượng mạng biến động khó đoán, kết nối gián đoạn và tài nguyên thiết bị hạn chế; khả năng tiếp tục hoạt động khi mất kết nối (disconnected operation) là yêu cầu cơ bản của loại ứng dụng này [6]. Hướng tiếp cận ưu tiên cục bộ (local-first) đáp ứng yêu cầu đó bằng cách đặt bản sao dữ liệu chính trên thiết bị của người dùng; máy chủ đóng vai trò đồng bộ và sao lưu thay vì là điều kiện để ứng dụng hoạt động [7]. Kiến trúc ưu tiên ngoại tuyến (offline-first) của đề tài vận dụng nguyên lý này: ứng dụng đọc và ghi trên cơ sở dữ liệu cục bộ, việc trao đổi với máy chủ diễn ra khi có kết nối. Hệ quả là mỗi thao tác ghi có hai thời điểm khác nhau: thời điểm dữ liệu được lưu trên thiết bị và thời điểm thay đổi đó được máy chủ xác nhận. Trạng thái cục bộ chưa đồng bộ vì vậy phải được hiểu là dữ liệu đang chờ trao đổi, không phải dữ liệu đã được máy chủ lưu thành công.'),
    ('p', 'Việc ghi được khi mất kết nối có cái giá về tính nhất quán, được định lý CAP chỉ ra: một hệ thống dữ liệu phân tán không thể đồng thời bảo đảm tính nhất quán (consistency), tính sẵn sàng (availability) và khả năng chịu phân vùng mạng (partition tolerance), nên khi mạng bị chia cắt phải chọn giữa nhất quán và sẵn sàng. Định lý được Gilbert và Lynch chứng minh hình thức [10] và được Brewer phân tích lại với góc nhìn thực dụng hơn [11]. Ứng dụng ưu tiên ngoại tuyến chọn tính sẵn sàng: cho phép ghi cục bộ ngay cả khi không liên lạc được với máy chủ, và chấp nhận rằng các bản sao chỉ hội tụ sau một khoảng thời gian. Mô hình nhất quán cuối cùng (eventual consistency) mô tả đúng hành vi này: nếu không có thay đổi mới, mọi bản sao cuối cùng sẽ có cùng giá trị [12].'),
    ('p', 'Khi nhiều bản sao cùng được sửa độc lập, xung đột là điều khó tránh, và hệ thống phải quyết định thay đổi nào được giữ lại. Hệ thống Bayou đề xuất việc phát hiện và giải quyết xung đột theo ngữ nghĩa của ứng dụng trong môi trường lưu trữ nhân bản kết nối yếu [13]. Một chiến lược đơn giản hơn là last-write-wins (LWW – bản ghi sau cùng thắng), dựa trên việc sắp xếp các sự kiện theo dấu thời gian; tuy nhiên, thứ tự theo đồng hồ vật lý chỉ là thứ tự gần đúng vì đồng hồ của các thiết bị không hoàn toàn đồng bộ [14]. Ở hướng ngược lại, các kiểu dữ liệu nhân bản không xung đột (CRDT) được thiết kế để các bản sao hội tụ mà không cần phân xử tập trung [15], nhưng đòi hỏi mô hình dữ liệu và thuật toán phức tạp hơn.'),
    ('p', 'Với AgriLog V2, dữ liệu của mỗi nông hộ chủ yếu do một người dùng trên một thiết bị chỉnh sửa, nên khả năng hai bản sao cùng sửa một bản ghi là thấp. Nhóm chọn last-write-wins kết hợp quy tắc xóa thắng sửa vì dễ giải thích với người dùng và dễ kiểm thử, đồng thời bổ sung cơ chế trả bản ghi bị từ chối kèm lý do để việc loại bỏ thay đổi không diễn ra âm thầm; giao thức đồng bộ và các tình huống xung đột được thiết kế ở mục 3.3.'),

    # ------------------------------------------------------------------ 2.3
    ('h2', 314, 'Dịch vụ REST, xác thực và kiểm soát truy cập'),
    ('p', 'REST (Representational State Transfer) là một phong cách kiến trúc cho hệ thống siêu phương tiện phân tán, được định nghĩa bằng một tập ràng buộc: tách biệt client–server, không lưu trạng thái phiên trên máy chủ (stateless), cho phép bộ nhớ đệm, giao diện thống nhất và hệ thống phân tầng [16]. Tính không trạng thái khiến mỗi yêu cầu phải mang đủ thông tin để máy chủ xử lý, kể cả danh tính người gọi, qua đó dịch vụ dễ mở rộng ngang và dễ kiểm thử; giao thức đồng bộ và các điểm cuối nghiệp vụ của AgriLog V2 được thiết kế theo phong cách này. JSON Web Token (JWT) là cơ chế xác thực phù hợp với ràng buộc đó: mã đăng nhập có chữ ký, mang thông tin định danh của người dùng và thời hạn hiệu lực, được máy chủ xác minh mà không cần lưu phiên [17]. Các nghiên cứu về lược đồ xác thực dựa trên JWT cũng chỉ ra những lưu ý khi sử dụng như bảo vệ khóa ký và đặt thời hạn mã hợp lý [18]. Trong AgriLog V2, JWT là cơ chế xác thực duy nhất cho các điểm cuối cần bảo vệ.'),
    ('p', 'Xác thực chỉ cho biết người gọi là ai; việc người đó được phép làm gì thuộc về kiểm soát truy cập. Mô hình kiểm soát truy cập theo vai trò (Role-Based Access Control – RBAC) gán quyền cho vai trò thay vì gán trực tiếp cho từng người dùng; người dùng được cấp quyền thông qua vai trò của mình [19]. Cách tiếp cận này đơn giản hóa quản trị phân quyền khi hệ thống có nhiều người dùng cùng nhóm. AgriLog V2 sử dụng hai vai trò là quản trị viên và nông hộ; do vai trò không phân biệt được dữ liệu của nông hộ này với dữ liệu của nông hộ khác, RBAC được kết hợp với kiểm tra quyền sở hữu trên từng bản ghi.'),
    ('p', 'Yêu cầu về quyền sở hữu xuất phát từ đặc điểm của cơ sở dữ liệu dùng chung cho nhiều người dùng (multi-tenant): dữ liệu của mỗi người dùng phải được cô lập và kiểm soát truy cập ở mọi đường truy cập đến dữ liệu [20]. Giao diện người dùng không phải là ranh giới bảo mật: nghiên cứu về các giao diện lập trình của ứng dụng di động cho thấy sự không nhất quán giữa phần kiểm tra ở ứng dụng và phần kiểm tra ở máy chủ có thể dẫn đến lỗ hổng [21]. Vì vậy, vai trò và quyền sở hữu phải được kiểm tra tại máy chủ đối với cả điểm cuối REST lẫn đường đồng bộ, và thông tin định danh phải lấy từ ngữ cảnh xác thực thay vì từ dữ liệu do máy khách gửi lên (mục 3.5).'),

    # ------------------------------------------------------------------ 2.4
    ('h2', 323, 'Cơ sở dữ liệu, giao dịch và tính toán số tiền'),
    ('p', 'Mô hình quan hệ biểu diễn dữ liệu dưới dạng các quan hệ (bảng) và cho phép truy vấn độc lập với cách lưu trữ vật lý [22]; mô hình này phù hợp với dữ liệu sổ sách của nông hộ, vốn gồm nhiều loại bản ghi có quan hệ chặt với nhau. Để đi từ nghiệp vụ đến các bảng, mô hình thực thể – liên kết (ER) mô tả thế giới thực bằng các thực thể, thuộc tính và mối liên kết, thường được dùng để thiết kế cơ sở dữ liệu quan hệ trước khi cài đặt [23]. Lược đồ cơ sở dữ liệu của AgriLog V2 được thiết kế theo mô hình ER và cài đặt thành 16 bảng quan hệ (mục 3.4).'),
    ('p', 'Khi cập nhật, tính toàn vẹn của dữ liệu được bảo đảm bằng giao dịch: đơn vị công việc phải thỏa các tính chất nguyên tử (atomicity), nhất quán (consistency), cô lập (isolation) và bền vững (durability), thường được viết tắt là ACID [24]. Tính nguyên tử bảo đảm một lô thao tác hoặc được thực hiện trọn vẹn, hoặc không thực hiện phần nào. Đặc tính này đặc biệt hữu ích cho đồng bộ: một lô thay đổi gửi từ thiết bị được xử lý như một giao dịch, nên việc gửi lại sau lỗi không để lại dữ liệu ghi dở.'),
    ('p', 'Với dữ liệu tiền tệ, tính đúng đắn còn phụ thuộc vào cách biểu diễn và làm tròn. Số thực dấu phẩy động nhị phân không biểu diễn chính xác mọi giá trị thập phân và có thể sinh sai số làm tròn [25]. Chuẩn IEEE 754 quy định chế độ làm tròn mặc định là làm tròn đến giá trị gần nhất, hòa thì về số chẵn (roundTiesToEven) [26]; hàm round của Python hành xử theo cách này, trong khi hàm Math.round của JavaScript làm tròn nửa lên. Khi cùng một phép tính tiền được thực hiện ở hai ngôn ngữ, sự khác biệt này có thể gây lệch một đồng. AgriLog V2 viết các quy tắc nghiệp vụ cần chạy ngoại tuyến ở cả máy chủ và ứng dụng di động, nên hệ thống cần một quy tắc làm tròn thống nhất và được kiểm thử ở cả hai phía (các mục 3.3.5 và 4.2.2).'),

    # ------------------------------------------------------------------ 2.5
    ('h2', 330, 'Quy trình phát triển phần mềm, đặc tả yêu cầu và kiểm thử'),
    ('p', 'Về quy trình phát triển, mô hình thác nước (waterfall) chia phát triển thành các giai đoạn tuần tự từ yêu cầu, thiết kế, cài đặt đến kiểm thử [27], phù hợp khi yêu cầu ổn định. Mô hình xoắn ốc kết hợp tính lặp của mô hình nguyên mẫu với tính hệ thống của mô hình thác nước và lấy phân tích rủi ro làm trục điều khiển [8]. Do yêu cầu của AgriLog V2 được làm rõ dần qua từng giai đoạn, đề tài áp dụng cách tiếp cận lặp: mỗi giai đoạn gồm phân tích, thiết kế, cài đặt và kiểm thử cho một nhóm chức năng.'),
    ('p', 'Ở bước xác định yêu cầu, tiêu chuẩn ISO/IEC/IEEE 29148 hướng dẫn quá trình kỹ nghệ yêu cầu, trong đó yêu cầu cần được phát biểu rõ ràng, có thể kiểm chứng và truy vết được [28]; yêu cầu thường được phân thành yêu cầu chức năng và yêu cầu phi chức năng. Ở bước thiết kế, tiêu chuẩn IEEE 1016 quy định nội dung của tài liệu mô tả thiết kế phần mềm, trong đó có các góc nhìn về ngữ cảnh, thành phần, dữ liệu, giao diện và hành vi [29]. Ngôn ngữ mô hình hóa thống nhất (UML) cung cấp các biểu đồ tương ứng: biểu đồ use case biểu diễn tương tác giữa tác nhân và hệ thống, biểu đồ tuần tự biểu diễn thứ tự thông điệp giữa các thành phần theo thời gian. Chương 3 áp dụng các khái niệm trên khi đặc tả yêu cầu (mục 3.1) và mô hình hóa các luồng xử lý (mục 3.2).'),
    ('p', 'Kiểm thử phần mềm là quá trình thực thi hệ thống nhằm kiểm tra sự phù hợp với yêu cầu và phát hiện lỗi; tiêu chuẩn ISO/IEC/IEEE 29119-1 định nghĩa các khái niệm nền tảng như mức kiểm thử, kỹ thuật kiểm thử và chiến lược kiểm thử [30]. Độ phủ (coverage) đo tỷ lệ mã được thực thi bởi bộ kiểm thử, nhưng nghiên cứu thực nghiệm cho thấy độ phủ chỉ có tương quan thấp đến vừa với khả năng phát hiện lỗi của bộ kiểm thử khi đã loại trừ ảnh hưởng của kích thước bộ kiểm thử [31]. Vì vậy, báo cáo trình bày độ phủ cùng với số lượng, phạm vi nghiệp vụ và các lỗi thực tế đã phát hiện, không dùng độ phủ như bằng chứng duy nhất về chất lượng.'),
    ('p', 'Khi đo hiệu năng, độ trễ trung bình có thể che giấu những yêu cầu chậm bất thường; để mô tả trải nghiệm thực tế, cần xem các phân vị cao của phân bố độ trễ, chẳng hạn p95 hoặc p99 [32]. Phân vị p95 là giá trị mà 95% số yêu cầu có thời gian xử lý không vượt quá, còn 5% còn lại có thể chậm hơn. Kết quả kiểm tải chỉ có ý nghĩa khi đi kèm cấu hình môi trường thử nghiệm và loại thao tác được đo (mục 4.5.4).'),

    # ------------------------------------------------------------------ 2.6
    ('h2', 339, 'Khả năng tiếp cận giao diện và minh bạch nguồn dữ liệu nông học'),
    ('p', 'Thông tin mà ứng dụng cung cấp chỉ có giá trị sử dụng khi người dùng đọc được và biết nó dựa trên căn cứ nào; yêu cầu thứ nhất thuộc về hình thức trình bày, yêu cầu thứ hai thuộc về nội dung. Về hình thức, hướng dẫn WCAG 2.1 đặt ra các tiêu chí giúp nội dung dễ tiếp cận hơn; về độ tương phản màu, văn bản thông thường cần tỷ lệ tối thiểu 4,5:1 ở mức AA và 7:1 ở mức AAA [33]. Đề tài dùng tiêu chí này để kiểm tra độ tương phản của màu chữ trên giao diện di động. Kết quả đó là tự kiểm tra của nhóm, không phải chứng nhận độc lập cho toàn bộ ứng dụng.'),
    ('p', 'Về nội dung, dữ liệu nông học như thời gian sinh trưởng, định mức phân bón hay quy trình chăm sóc phụ thuộc giống, giai đoạn sinh trưởng và điều kiện canh tác; nếu không có nguồn, người dùng khó xác định phạm vi áp dụng. Khó khăn trong chia sẻ và thống nhất dữ liệu giữa các thành phần phần mềm cũng được nêu là một trở ngại của hệ sinh thái phần mềm nông nghiệp [9]. AgriLog V2 vì vậy gắn nguồn cho từng giống và quy trình, dựa trên các văn bản chính thống như Quyết định 1972/QĐ-UBND của UBND tỉnh Lâm Đồng [34] và Quyết định 254/QĐ-TT-CCN của Cục Trồng trọt [35], và hiển thị “Chưa có dữ liệu” khi thiếu căn cứ thay vì tự điền giá trị. Liên kết nguồn không đồng nghĩa nội dung đã được thẩm định độc lập. Cả hai yêu cầu được cụ thể hóa thành nguyên tắc thiết kế giao diện ở mục 3.7.1.'),

    # ------------------------------------------------------------------ 2.7
    ('h2', 344, 'Các công trình liên quan và định hướng của đề tài'),
    ('h3', 345, 'Các hướng nghiên cứu và giải pháp liên quan'),
    ('p', 'Qua khảo sát tài liệu, các công trình liên quan đến đề tài có thể được phân thành bốn hướng.'),
    ('p', '1) **Tổng quan về hệ thống thông tin quản lý nông trại.** Fountas và cộng sự [3] tổng kết hiện trạng và triển vọng của FMIS, cho thấy các hệ thống ngày càng mở rộng từ ghi chép đơn thuần sang hỗ trợ ra quyết định. Tummers và cộng sự [4] thực hiện tổng quan tài liệu có hệ thống về các trở ngại và đặc tính của FMIS. Hai công trình này cung cấp khung chức năng tham chiếu để đề tài xác định phạm vi các phân hệ, nhưng không hướng tới một sản phẩm cụ thể cho nông hộ nhỏ.'),
    ('p', '2) **FMIS cho nông hộ quy mô nhỏ.** Henriyadi và cộng sự [5] đề xuất mô hình khái niệm để phát triển FMIS cho nông hộ nhỏ, với trường hợp nông hộ trồng ớt tại Indonesia. Đây là căn cứ cho định hướng giữ hệ thống đơn giản, tập trung vào chức năng cốt lõi. Công trình tập trung ở mức mô hình khái niệm; các vấn đề cài đặt như vận hành ngoại tuyến và đồng bộ dữ liệu không phải trọng tâm.'),
    ('p', '3) **Kiến trúc và hạ tầng cho phần mềm nông nghiệp.** Kruize và cộng sự [9] đề xuất kiến trúc tham chiếu cho hệ sinh thái phần mềm nông trại, nhấn mạnh khả năng trao đổi dữ liệu giữa các thành phần. Ahmed và cộng sự [1] nghiên cứu giải pháp Internet vạn vật cho nông nghiệp ở vùng nông thôn, nơi hạ tầng kết nối là ràng buộc chính. Hai công trình tiếp cận ở tầng hệ sinh thái và hạ tầng; đề tài tiếp nhận từ đó hai ràng buộc thiết kế: thống nhất dữ liệu dùng chung giữa các thành phần và không giả định kết nối luôn sẵn có.'),
    ('p', '4) **Phần mềm ưu tiên cục bộ và đồng bộ dữ liệu.** Kleppmann và cộng sự [7] nêu các nguyên tắc của phần mềm local-first, trong đó dữ liệu thuộc về thiết bị của người dùng; Terry và cộng sự [13] trình bày cách quản lý xung đột cập nhật trong hệ lưu trữ nhân bản kết nối yếu; Shapiro và cộng sự [15] đề xuất các kiểu dữ liệu nhân bản không xung đột. Các công trình này là nền tảng chung cho kiến trúc ở mục 2.2, không gắn với nghiệp vụ nông nghiệp.'),
    ('orig', 351),   # "Bên cạnh các công trình học thuật..." (giữ nguyên)
    ('orig', 352),   # chú thích Bảng 2.1
    ('orig', 353),   # Bảng 2.1
    ('h3', 354, 'Đối chiếu và phạm vi đóng góp của đề tài'),
    ('p', 'Đặt bốn hướng cạnh nhau, có thể thấy trong phạm vi các công trình được khảo sát, nhóm FMIS xác định nghiệp vụ và rào cản của nông hộ nhỏ nhưng không lấy vận hành ngoại tuyến làm trọng tâm, còn nhóm phần mềm ưu tiên cục bộ giải quyết vận hành ngoại tuyến và đồng bộ nhưng không gắn với nghiệp vụ nông nghiệp. Bài toán của đề tài nằm ở phần giao của hai nhóm này. Bảng 2.2 đối chiếu đề tài với các nhóm công trình đã khảo sát; đây là so sánh theo phạm vi và đặc tính của công trình, không phải kết quả thử nghiệm so sánh hiệu năng, và báo cáo không kết luận AgriLog V2 vượt trội một sản phẩm thương mại cụ thể.'),
    ('orig', 356),   # chú thích Bảng 2.2
    ('orig', 357),   # Bảng 2.2
    ('p177', 'Từ đối chiếu trên, điểm khác biệt của đề tài thể hiện ở hai mặt. Về nghiệp vụ, đề tài gộp lô đất, vụ trồng, công việc chăm sóc, vật tư và thu – chi của nông hộ vào một luồng dữ liệu thống nhất, gắn với dữ liệu nông học có nguồn. Về kỹ thuật, đề tài hiện thực một hệ thống ưu tiên ngoại tuyến cho bài toán này, trong đó đồng bộ, xử lý xung đột và phân quyền được thiết kế như các thành phần cốt lõi và được kiểm chứng bằng kiểm thử tự động. Đóng góp này mang tính vận dụng: đề tài không đề xuất thuật toán đồng bộ mới mà áp dụng các nguyên lý đã có vào một bài toán nghiệp vụ cụ thể.'),

    # ------------------------------------------------------------------ 2.8
    ('h2', 359, 'Công nghệ và công cụ được lựa chọn'),
    ('orig', 360),   # "Mục này chỉ trình bày những công nghệ thực sự được sử dụng..." (giữ nguyên)
    ('p', 'Ứng dụng di động được xây dựng bằng React Native 0.81 với React 19.1 và TypeScript 5.8, điều hướng bằng React Navigation 7. React Native thuộc nhóm tiếp cận đa nền tảng đã được khảo sát trong [36], cho phép xây dựng ứng dụng bằng một mã nguồn theo mô hình thành phần và dùng chung ngôn ngữ, kiểu dữ liệu với trang quản trị. Lớp cơ sở dữ liệu cục bộ là WatermelonDB 0.28 trên SQLite (lược đồ phiên bản 7 gồm 13 bảng): màn hình quan sát trực tiếp dữ liệu cục bộ nên tự cập nhật khi bản ghi thay đổi, và thư viện có sẵn khung đồng bộ kéo về/đẩy lên (pull/push) phù hợp với kiến trúc ưu tiên ngoại tuyến ở mục 2.2. Về thư viện hỗ trợ, react-native-keychain giữ mã đăng nhập trong kho khóa của hệ điều hành; các thư viện còn lại phục vụ chọn và lưu tạm ảnh, video, phát video nhúng, xuất báo cáo và vẽ biểu đồ (Bảng 2.3).'),
    ('p', 'Ở phía máy chủ, dịch vụ REST [16] được xây dựng bằng FastAPI (trên Starlette, chạy bằng Uvicorn) và Pydantic 2: Pydantic kiểm tra kiểu và ràng buộc của dữ liệu đầu vào, còn FastAPI tự sinh tài liệu OpenAPI cho toàn bộ 82 điểm cuối. SQLAlchemy 2.0 là lớp ánh xạ đối tượng – quan hệ (ORM), cho phép cùng một mô hình dữ liệu chạy trên SQLite khi phát triển, kiểm thử và trên PostgreSQL khi triển khai. PostgreSQL 16 là hệ quản trị cơ sở dữ liệu quan hệ [22] của môi trường triển khai, hỗ trợ giao dịch ACID [24] cần cho việc xử lý nguyên tử từng lô đồng bộ. PyJWT phát hành và xác minh mã JWT [17], bcrypt băm mật khẩu, còn fpdf2 sinh báo cáo PDF hỗ trợ tiếng Việt.'),
    ('p', 'Trang quản trị được xây dựng bằng Next.js 16 (App Router) với React 19, TypeScript và Tailwind CSS 4. Next.js cung cấp định tuyến theo thư mục và bản dựng (build) tối ưu cho trình duyệt; Tailwind CSS cho phép dùng chung bộ token thiết kế (màu, khoảng cách, phông chữ) với ứng dụng di động. Trang quản trị không có tầng dữ liệu riêng mà gọi cùng API với ứng dụng di động, nên quy tắc phân quyền chỉ cần hiện thực một lần ở máy chủ, đúng với nguyên tắc kiểm tra tại máy chủ ở mục 2.3.'),
    ('p', 'Bảng 2.3 tổng hợp các công nghệ theo thành phần, gồm cả công cụ kiểm thử và dữ liệu dùng chung. Bảng 2.4 đối chiếu từng lựa chọn với phương án thay thế phổ biến theo các ràng buộc của đề tài; đây là các tiêu chí định tính về kiến trúc và vận hành, không phải kết quả đo đạc thực nghiệm.'),
    ('orig', 374),   # chú thích Bảng 2.3
    ('orig', 375),   # Bảng 2.3
    ('orig', 376),   # chú thích Bảng 2.4
    ('orig', 377),   # Bảng 2.4
]

